legacy, reader = client_with_catalogs()\\n+    calls = lifecycle_probes(client)\\n+    reader.get_readiness = lambda **scope: admission\\n+    response = client.get(LIFECYCLE_PATH)\\n+    assert response.status_code == 503\\n+    assert 'CREATOR_LIFECYCLE_READ_ADMISSION_UNAVAILABLE' in response.text\\n+    assert 'latestStart' not in response.text\\n+    assert calls == [] and not legacy.calls\\n+\\n+\\n+@pytest.mark.parametrize('code', ['CREATOR_LIFECYCLE_READ_UNAVAILABLE',\\n+    'CREATOR_LIFECYCLE_READ_AUTHORITY_DRIFT', 'CREATOR_LIFECYCLE_READ_LIMIT_EXCEEDED'])\\n+def test_lifecycle_bounded_failure_stays_explicit_503(code):\\n+    client, legacy, reader = client_with_catalogs()\\n+    calls = lifecycle_probes(client, failure=code)\\n+    reader.get_readiness = lambda **scope: lifecycle_admission()\\n+    response = client.get(LIFECYCLE_PATH)\\n+    assert response.status_code == 503 and code in response.text\\n+    assert 'latestStart' not in response.text\\n+    assert calls == [('readonly', ('org-org', 'dev-project'))] and not legacy.calls\\n+\\n+\\n+def test_lifecycle_readonly_serializes_genuine_empty_without_commands():\\n+    from datetime import datetime, timezone\\n+    from aos_api.ecommerce_workshop_creator_lifecycle import CreatorLifecycleView, _ledger\\n+    client, legacy, reader = client_with_catalogs()\\n+    reader.get_readiness = lambda **scope: lifecycle_admission()\\n+    class Readonly:\\n+        def read(self, scope):\\n+            return CreatorLifecycleView(\\n+                tenant=dict(orgId=scope.org_id, projectId=scope.project_id),\\n+                evaluatedAt=datetime(2026, 10, 14, tzinfo=timezone.utc),\\n+                latestStart=None, ledger=_ledger([], 0), contracts=[], deliveries=[],\\n+                relationships=[], blockers=['CREATOR_BATCH_START_NOT_AVAILABLE'],\\n+                allowedCommands=[], externalEffectsAllowed=False,\\n+            )\\n+    class Legacy:\\n+        def view(self, scope):\\n+            pytest.fail('installed readonly must never invoke legacy view')\\n+    client.app.dependency_overrides[routes.get_creator_lifecycle_readonly] = lambda: Readonly()\\n+    client.app.dependency_overrides[routes.get_ecommerce_workshop_creator_lifecycle] = lambda: Legacy()\\n+    response = client.get(LIFECYCLE_PATH)\\n+    assert response.status_code == 200\\n+    data = response.json()\\n+    assert data['tenant'] == dict(orgId='org-org', projectId='dev-project')\\n+    assert data['latestStart'] is None and data['contracts'] == []\\n+    assert data['allowedCommands'] == [] and data['externalEffectsAllowed'] is False\\n+    assert not legacy.calls\\n\\n\\nACTUAL FUNCTION get_ecommerce_workshop_read_catalog\\ndef get_ecommerce_workshop_read_catalog(\\n    legacy: Annotated[EcommerceWorkshopCatalog, Depends(get_ecommerce_workshop_catalog)],\\n) -> EcommerceWorkshopReadCatalog:\\n    from aos_api.ecommerce_installed_readonly_catalog import build_installed_readonly_catalog\\n\\n    return EcommerceWorkshopReadCatalog(\\n        legacy=legacy,\\n        installed_factory=build_installed_readonly_catalog,\\n    )\\n\\nACTUAL FUNCTION get_creator_lifecycle_readonly\\ndef get_creator_lifecycle_readonly() -> CreatorLifecycleReadonlyReader:\\n    return CreatorLifecycleReadonlyReader()\\n\\nACTUAL FUNCTION _reject_query_parameters\\ndef _reject_query_parameters(request: Request) -> None:\\n    if request.query_params:\\n        raise ApiError(\\n            code=\\\"VALIDATION\\\",\\n            message=\\\"ecommerce Workshop reads do not accept query parameters\\\",\\n            status_code=400,\\n        )\\n\\nACTUAL FUNCTION _invoke\\ndef _invoke(operation: Callable[[], ResultT]) -> ResultT:\\n    try:\\n        return operation()\\n    except AssetRegistryError as exc:\\n        raise ApiError(\\n            code=exc.code.value,\\n            message=str(exc),\\n            status_code=exc.http_status,\\n            details=exc.details,\\n        ) from exc\\n\\nACTUAL FUNCTION _require_creator_growth_installation\\ndef _require_creator_growth_installation(\\n    *, principal: Principal, catalog: EcommerceWorkshopCatalog\\n) -> EcommerceWorkshopModuleReadinessResponse:\\n    return _invoke(\\n        lambda: catalog.get_readiness(\\n            module_id=\\\"ecommerce.creator-growth\\\",\\n            org_id=principal.org_id,\\n            project_id=principal.project_id,\\n            roles=principal.roles,\\n            markings=principal.markings,\\n        )\\n    )\\n\\nACTUAL FUNCTION get_creator_lifecycle_view\\ndef get_creator_lifecycle_view(\\n    request: Request,\\n    principal: PrincipalDependency,\\n    catalog: ReadCatalogDependency,\\n    service: CreatorLifecycleDependency,\\n    readonly: CreatorLifecycleReadonlyDependency,\\n) -> CreatorLifecycleView:\\n    _reject_query_parameters(request)\\n    admission = _require_creator_growth_installation(principal=principal, catalog=catalog)\\n    if not isinstance(admission, EcommerceWorkshopModuleReadinessResponse):\\n        raise ApiError(\\n            code=\\\"CREATOR_LIFECYCLE_READ_ADMISSION_UNAVAILABLE\\\",\\n            message=\\\"当前生命周期读取准入不可核验。\\\",\\n            status_code=503,\\n        )\\n    scope = TenantScope(principal.org_id, principal.project_id)\\n    if any(blocker.reason_code == \\\"INSTALLED_ASSET_READONLY\\\" for blocker in admission.item.blockers):\\n        try:\\n            return readonly.read(scope)\\n        except CreatorLifecycleReadonlyError as exc:\\n            raise ApiError(\\n                code=exc.code,\\n                message=\\\"当前生命周期数据暂不可读，请核对数据或读取范围。\\\",\\n                status_code=503,\\n            ) from exc\\n    return service.view(scope)\\n\\nPRODUCT/TEST SOURCE SHA services/aos-api/aos_api/routers/ecommerce_workshop.py 71eb6e6169def936cb023c3a800355847ae45370d9cc68dad2d4266b4fb0c66c\\n\\nPRODUCT/TEST SOURCE SHA services/aos-api/tests/test_ecommerce_workshop_read_http.py 3f7190e63d8843747ceb5f8e00baa1f336224160f54df03761cef72d3de5ec5e\\n\\nPRODUCT/TEST SOURCE SHA services/aos-api/aos_api/ecommerce_workshop_creator_lifecycle_readonly.py 95cacb071c8f9b10ad4ba3277c1a2820db076ba527c53d6d964b801fd01b7780\\n\\nPRODUCT/TEST SOURCE SHA services/aos-api/tests/aip/test_creator_lifecycle_readonly.py 84b7eefe943649b83b1e22ea9e1c8b7ac0e5ea0693a40f40c705e78dd3d8e91d\"}}"}],"timestamp":1791980640339}}
